    [DataContract] public sealed class SabrFormat {
        [DataMember] public string id;
        [DataMember] public string lastModified;
        [DataMember] public string xtags;
        [DataMember] public string mime;
        internal byte[] Encode(){ulong itag,lmt;if(!ulong.TryParse(id,out itag)||itag==0||itag>999999||!ulong.TryParse(lastModified,out lmt)||lmt==0)throw new ArgumentException("The browser did not capture a complete stream identity.");var p=new Proto().Set(1,itag).Set(2,lmt);if(!string.IsNullOrEmpty(xtags)){if(xtags.Length>2048)throw new ArgumentException("Invalid stream tags.");p.Set(3,xtags);}return p.Encode();}
    }
    [DataContract] public sealed class SabrOffer {
        [DataMember] public string url;
        [DataMember] public string body;
        [DataMember] public string videoId;
        [DataMember] public double capturedAt;
        [DataMember] public long durationMs;
        [DataMember] public SabrFormat video;
        [DataMember] public SabrFormat audio;
