    }
    public sealed partial class Manager {
        public Download AddSabr(string source,string name,int height,int pixelHeight,SabrOffer offer,Dictionary<string,string> headers){
            if(offer==null)throw new ArgumentException("Browser streaming capture is missing.");offer.Validate(source);if(height<144||height>4320||pixelHeight<1||pixelHeight>4320)throw new ArgumentException("Invalid stream dimensions.");MediaTransfer.RequireTool("ffmpeg.exe");
            lock(Sync){var job=Add(source,null,Names.MediaTitle(name),"Main queue",true,headers,"",null);try{job.SourceUrl=source;job.MediaHeight=height;job.MediaPixelHeight=pixelHeight;job.MediaFormatId=offer.video.id;job.ExactMediaQuality=true;job.ProtectedSabr=Secrets.Protect(Json.Write(offer));MediaTransfer.SetStreams(this,job,offer.url,offer.url,"Browser streaming capture · "+height+"p");job.Status="Queued";Save();return job;}catch{State.Downloads.Remove(job);Save();throw;}}
        }
    }
